import{J as e,n as t,ot as n,q as r}from"./chunks/framework.8ZHN87l8.js";var i=JSON.parse(`{"title":"Class: LightEngine","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: LightEngine"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/lighting/classes/LightEngine"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/lighting/classes/LightEngine"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/lighting/src"}},"headers":[],"relativePath":"api/@jsprismarine/lighting/classes/LightEngine.md","filePath":"api/@jsprismarine/lighting/classes/LightEngine.md","lastUpdated":1793831485000}`),a={name:`api/@jsprismarine/lighting/classes/LightEngine.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/lighting</a> / LightEngine</p><h1 id="class-lightengine" tabindex="-1">Class: LightEngine <a class="header-anchor" href="#class-lightengine" aria-label="Permalink to “Class: LightEngine”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L78" target="_blank" rel="noreferrer">LightEngine.ts:78</a></p><p>The server&#39;s internal light model: a block light layer that floods out of emitters and a sky light layer that falls from the open sky, both kept current as blocks change and both advanced in bounded steps so a tick cannot stall.</p><p>These levels never reach a player. The Bedrock protocol has no light packet and neither <code>LevelChunkPacket</code> nor <code>SubChunkPacket</code> carries light arrays, so the connected client computes and renders light itself from the block palette it already has. The server keeps its own copy for the three rules that read it: mob spawning, crop growth, and daylight detectors. Where the two models disagree, the player sees the client&#39;s answer and the server acts on this one.</p><p>Java&#39;s directional opacity, which lets a slab, a stair or a piston pass light in some directions and not others, is deliberately not implemented. Bedrock&#39;s block data expresses one <code>minecraft:light_dampening</code> scalar per state with no direction, the Bedrock client applies that scalar, and a server that modeled Java&#39;s per-face rule would compute light the client contradicts for every slab and stair in the world.</p><p>The engine reads the world through an injected <a href="./../#blocklightview">BlockLightView</a> and holds no reference to chunk, block or world classes. The server has to announce a chunk with <a href="#onchunkloaded">LightEngine.onChunkLoaded</a> before the engine stores light in it.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new LightEngine</strong>(<code>view</code>): <code>LightEngine</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L84" target="_blank" rel="noreferrer">LightEngine.ts:84</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="view" tabindex="-1">view <a class="header-anchor" href="#view" aria-label="Permalink to “view”">​</a></h5><p><a href="./../#blocklightview"><code>BlockLightView</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>LightEngine</code></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="pending" tabindex="-1">pending <a class="header-anchor" href="#pending" aria-label="Permalink to “pending”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>pending</strong>(): <a href="./../#lightqueuedepth"><code>LightQueueDepth</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L92" target="_blank" rel="noreferrer">LightEngine.ts:92</a></p><p>The work the engine still has to do. <a href="#flush">LightEngine.flush</a> returns the same numbers.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><a href="./../#lightqueuedepth"><code>LightQueueDepth</code></a></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="flush" tabindex="-1">flush() <a class="header-anchor" href="#flush" aria-label="Permalink to “flush()”">​</a></h3><blockquote><p><strong>flush</strong>(<code>budget?</code>): <a href="./../#lightflushresult"><code>LightFlushResult</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L228" target="_blank" rel="noreferrer">LightEngine.ts:228</a></p><p>Advances the light by at most <code>budget</code> queue nodes and reports what is left, so a tick can spend a fixed amount of time on light and decide from the result whether to come back.</p><p>Every decrease node runs before any increase node, which is what makes a removed light source darken its neighborhood before the surviving sources fill it in again. Stopping mid-flush leaves the light part way through that sequence: levels are readable but not yet correct, and they become correct once <code>queued</code> reaches 0.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="budget" tabindex="-1">budget? <a class="header-anchor" href="#budget" aria-label="Permalink to “budget?”">​</a></h5><p><code>number</code> = <code>Number.POSITIVE_INFINITY</code></p><p>The most nodes to process. Unbounded when omitted.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#lightflushresult"><code>LightFlushResult</code></a></p><p>The work done and the work left.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the budget is negative or not a number.</p><hr><h3 id="getblocklight" tabindex="-1">getBlockLight() <a class="header-anchor" href="#getblocklight" aria-label="Permalink to “getBlockLight()”">​</a></h3><blockquote><p><strong>getBlockLight</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L104" target="_blank" rel="noreferrer">LightEngine.ts:104</a></p><p>The block light at a world position, 0 to 15.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The level, or 0 for a position in a column the engine has not been told about. Check that the chunk is loaded before reading a 0 as darkness.</p><hr><h3 id="getskylight" tabindex="-1">getSkyLight() <a class="header-anchor" href="#getskylight" aria-label="Permalink to “getSkyLight()”">​</a></h3><blockquote><p><strong>getSkyLight</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L119" target="_blank" rel="noreferrer">LightEngine.ts:119</a></p><p>The sky light at a world position, 0 to 15, before the time of day and the weather scale it. The daylight cycle multiplies this number; it does not change it.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y-1" tabindex="-1">y <a class="header-anchor" href="#y-1" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The level, 0 in a dimension with no sky and 0 for a position in a column the engine has not been told about.</p><hr><h3 id="haschunk" tabindex="-1">hasChunk() <a class="header-anchor" href="#haschunk" aria-label="Permalink to “hasChunk()”">​</a></h3><blockquote><p><strong>hasChunk</strong>(<code>chunkX</code>, <code>chunkZ</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L87" target="_blank" rel="noreferrer">LightEngine.ts:87</a></p><p>Whether this engine currently holds lighting for a chunk column.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><h5 id="chunkz" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="onblockchanged" tabindex="-1">onBlockChanged() <a class="header-anchor" href="#onblockchanged" aria-label="Permalink to “onBlockChanged()”">​</a></h3><blockquote><p><strong>onBlockChanged</strong>(<code>position</code>, <code>oldState</code>, <code>newState</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L198" target="_blank" rel="noreferrer">LightEngine.ts:198</a></p><p>Queues the smallest piece of work that makes both layers correct again after one block changed. Nothing is computed here; <a href="#flush">LightEngine.flush</a> does the computing.</p><p>The sky layer is patched rather than rebuilt: the column&#39;s heightmap entry moves only when the change was at or above the highest light-blocking block, and the only scan is the walk down the column that finds the next blocker after the top one is broken.</p><p>A change that alters neither emission nor dampening queues nothing, so a server can call this for every block change without filtering first.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position" tabindex="-1">position <a class="header-anchor" href="#position" aria-label="Permalink to “position”">​</a></h5><p><a href="./../#blockposition"><code>BlockPosition</code></a></p><p>Where the block changed.</p><h5 id="oldstate" tabindex="-1">oldState <a class="header-anchor" href="#oldstate" aria-label="Permalink to “oldState”">​</a></h5><p><a href="./../#blocklightproperties"><code>BlockLightProperties</code></a></p><p>The light properties of the block that was there.</p><h5 id="newstate" tabindex="-1">newState <a class="header-anchor" href="#newstate" aria-label="Permalink to “newState”">​</a></h5><p><a href="./../#blocklightproperties"><code>BlockLightProperties</code></a></p><p>The light properties of the block that is there now.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onchunkloaded" tabindex="-1">onChunkLoaded() <a class="header-anchor" href="#onchunkloaded" aria-label="Permalink to “onChunkLoaded()”">​</a></h3><blockquote><p><strong>onChunkLoaded</strong>(<code>chunkX</code>, <code>chunkZ</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L136" target="_blank" rel="noreferrer">LightEngine.ts:136</a></p><p>Takes a chunk into the light model and computes its light from scratch: it builds the sky heightmap, makes every emitter in the column a source, and re-seeds across the border of each loaded neighbor so light that stopped at the chunk&#39;s edge while it was absent flows in.</p><p>Calling this for a chunk the engine already holds discards that chunk&#39;s stored light and computes it again, which is how a caller forces a full recompute.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx-1" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx-1" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><p>The chunk x.</p><h5 id="chunkz-1" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz-1" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><p>The chunk z.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="onchunkunloaded" tabindex="-1">onChunkUnloaded() <a class="header-anchor" href="#onchunkunloaded" aria-label="Permalink to “onChunkUnloaded()”">​</a></h3><blockquote><p><strong>onChunkUnloaded</strong>(<code>chunkX</code>, <code>chunkZ</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/2dcd6654541a0f713f1ec038372e3c8c46d74863/packages/lighting/src/LightEngine.ts#L180" target="_blank" rel="noreferrer">LightEngine.ts:180</a></p><p>Drops a chunk&#39;s stored light. Light in the neighbors that came from this chunk is left as it is; it is recomputed when the chunk comes back, because <a href="#onchunkloaded">LightEngine.onChunkLoaded</a> re-seeds across the border.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="chunkx-2" tabindex="-1">chunkX <a class="header-anchor" href="#chunkx-2" aria-label="Permalink to “chunkX”">​</a></h5><p><code>number</code></p><p>The chunk x.</p><h5 id="chunkz-2" tabindex="-1">chunkZ <a class="header-anchor" href="#chunkz-2" aria-label="Permalink to “chunkZ”">​</a></h5><p><code>number</code></p><p>The chunk z.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,135)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};